(window.CLAVE_TEST=window.CLAVE_TEST||{})[7]=[{"a":"Artículo 2 — Competencias ✱","q":[{"i":"7-ia-7003","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá, en los casos y en la forma que la Ley determina, del recurso y de la cuestión de inconstitucionalidad contra:","o":["Leyes y reglamentos del Estado y de las Comunidades Autónomas.","Leyes orgánicas y tratados internacionales exclusivamente.","Leyes, disposiciones normativas o actos con fuerza de Ley.","Leyes, reglamentos y actos administrativos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Leyes, disposiciones normativas o actos con fuerza de Ley</mark></span>El <span class=\"ref-norma\">art. 2.1.a de LOTC</span> dispone: <span class=\"ref-concepto\">\"Del recurso y de la cuestión de inconstitucionalidad contra Leyes, disposiciones normativas o actos con fuerza de Ley\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-141","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina:","o":["Del recurso de amparo por violación de cualesquiera derechos reconocidos en el Título I de la Constitución.","Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo 53.2 de la Constitución.","Del recurso de amparo contra las sentencias firmes dictadas por el Tribunal Supremo en cualquier orden jurisdiccional.","Del recurso de amparo por violación de los principios rectores de la política social y económica."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo 53.2 de la Constitución</mark></span>El <span class=\"ref-norma\">art. 2.1.b) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Del recurso de amparo por violación de los derechos y libertades públicos relacionados en el artículo cincuenta y tres, dos, de la Constitución.\"</span>. Solo son amparables los derechos y libertades del art. 53.2 CE (arts. 14 a 29 y la objeción de conciencia del 30), no todo el Título I. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-ia-7005","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de los conflictos constitucionales de competencia:","o":["entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.","entre el Estado y las Comunidades Autónomas exclusivamente, en los términos que establezca el propio Reglamento.","entre las Comunidades Autónomas y las entidades locales.","entre los órganos constitucionales del Estado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">entre el Estado y las Comunidades Autónomas o de los de éstas entre sí</mark></span>El <span class=\"ref-norma\">art. 2.1.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-154","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Competencias del Tribunal en Pleno. El Tribunal en Pleno conoce de los conflictos:","o":["De competencia entre las Entidades locales y las Comunidades Autónomas.","En defensa de la autonomía local.","Entre las Salas del propio Tribunal Constitucional.","De jurisdicción entre el Tribunal Supremo y los Tribunales Superiores de Justicia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">En defensa de la autonomía local</mark></span>El <span class=\"ref-norma\">art. 10.1.f) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"f) De los conflictos en defensa de la autonomía local.\"</span>"},{"i":"7-ia-7007","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de la declaración sobre la constitucionalidad:","o":["de los Reglamentos del Gobierno.","de los Decretos-leyes exclusivamente.","de los tratados internacionales.","de los convenios entre Comunidades Autónomas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">de los tratados internacionales</mark></span>El <span class=\"ref-norma\">art. 2.1.e de LOTC</span> dispone: <span class=\"ref-concepto\">\"De la declaración sobre la constitucionalidad de los tratados internacionales\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7009","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conocerá de la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar:","o":["si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.","si los mismos se han efectuado en los plazos previstos por la Constitución, conforme al procedimiento que se establezca reglamentariamente.","si los mismos respetan la composición paritaria de las Salas.","si los mismos cuentan con el respaldo de la mayoría de las Cámaras."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley</mark></span>El <span class=\"ref-norma\">art. 2.1.g de LOTC</span> dispone: <span class=\"ref-concepto\">\"De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-4","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina, entre otros, señale la incorrecta.","o":["Del recurso y de la cuestión de inconstitucionalidad contra Leyes, disposiciones normativas o actos con fuerza de Ley.","De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de los de éstas entre sí.","De los conflictos de defensa de la autonomía local.","De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley</mark></span>La opción D habla de Magistrados del Tribunal SUPREMO: es la falsa. Los conflictos en defensa de la autonomía local sí son de su competencia (art. 2.1.d bis). Según el <span class=\"ref-norma\">art. 2.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley\"</span> (verificado con el texto del temario)."},{"i":"7-65","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determine: señale la INCORRECTA.","o":["De la declaración sobre la constitucionalidad de los Tratados Internacionales.","De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.","De los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos.","De los conflictos en defensa de la autonomía local."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De los procesos de declaración de ilegalidad y consecuente disolución de los partidos políticos</mark></span>El <span class=\"ref-norma\">art. 2.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"d) De los conflictos entre los órganos constitucionales del Estado. d) bis. De los conflictos en defensa de la autonomía local. e) De la declaración sobre la constitucionalidad de los tratados internacionales.\"</span>."},{"i":"7-140","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional conocerá en los casos y en la forma que esta Ley determina: señale la INCORRECTA.","o":["Del recurso y de la cuestión de inconstitucionalidad contra Leyes, disposiciones normativas o actos con fuerza de Ley.","De los conflictos constitucionales de competencia entre el Estado y las Comunidades Autónomas o de uno de los éstos entre sí.","De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar a sí mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.","De los conflictos entre los órganos constitucionales del Estado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">De la verificación de los nombramientos de los Magistrados del Tribunal Supremo, para juzgar a sí mismos reúnen los requisitos requeridos por la Constitución y la presente Ley</mark></span>El <span class=\"ref-norma\">art. 2.1.g) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"g) De la verificación de los nombramientos de los Magistrados del Tribunal Constitucional, para juzgar si los mismos reúnen los requisitos requeridos por la Constitución y la presente Ley.\"</span>."},{"i":"7-85","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Qué órgano, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado?","o":["El Gobierno.","El Consejo General del Poder Judicial.","El Tribunal en Pleno.","Las Cortes Generales, a través de la comisión mixta Congreso - Senado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Tribunal en Pleno</mark></span>El <span class=\"ref-norma\">art. 10.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal en Pleno, en ejercicio de su autonomía como órgano constitucional, elabora su presupuesto, que se integra como una sección independiente dentro de los Presupuestos Generales del Estado.\"</span>. Es el Pleno quien elabora el presupuesto; el Presidente no lo aprueba."},{"i":"7-96","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. su organización y atribuciones. ¿Quién se encarga de convocar las Salas?","o":["El Presidente del Tribunal Constitucional.","El Presidente respectivo de cada Sala.","El Vicepresidente.","El Secretario del Tribunal Constitucional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Presidente del Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 27.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Son susceptibles de declaración de inconstitucionalidad: a) Los Estatutos de Autonomía y las demás Leyes orgánicas. b) Las demás Leyes, disposiciones normativas y actos del Estado con fuerza de Ley.\"</span>."},{"i":"7-47","p":"Ley Orgánica del Tribunal Constitucional. ¿Es necesaria la publicación de los reglamentos que dicte el Tribunal Constitucional sobre su propio funcionamiento y organización?","o":["No, al ser un documento interno no precisa de publicación.","Sí, debe ser publicado en el Boletín Oficial del Estado.","No, aunque si que podrá causar su publicación a efectos de derechos de terceros.","Sí, en el Boletín Oficial del Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Sí, debe ser publicado en el Boletín Oficial del Estado</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se publicarán en el «Boletín Oficial del Estado», autorizados por su Presidente.\"</span>."},{"i":"7-74","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional podrá dictar reglamentos sobre su propio funcionamiento y organización. Estos reglamentos:","o":["Deberán ser aprobados por el Pleno del Congreso de los Diputados.","Se publicarán en el «Boletín Oficial del Estado».","Deberán ser autorizados por los Presidentes del Congreso y del Senado.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Se publicarán en el «Boletín Oficial del Estado»</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se publicarán en el «Boletín Oficial del Estado», autorizados por su Presidente.\"</span>."},{"i":"7-ia-7010","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional podrá dictar reglamentos sobre su propio funcionamiento y organización, así como sobre el régimen de su personal y servicios. Estos reglamentos deberán ser:","o":["aprobados por el Tribunal en Pleno y publicados con la autorización del Gobierno, sin perjuicio de lo dispuesto en el Derecho nacional.","aprobados por las Salas y publicados en el «Boletín Oficial del Estado».","propuestos por el Presidente y aprobados por el Congreso de los Diputados.","aprobados por el Tribunal en Pleno y publicados en el «Boletín Oficial del Estado», autorizados por su Presidente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">aprobados por el Tribunal en Pleno y publicados en el «Boletín Oficial del Estado», autorizados por su Presidente</mark></span>El <span class=\"ref-norma\">art. 2.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-40","p":"Ley Orgánica del Tribunal Constitucional. En relación con el Tribunal Constitucional: Señale la opción incorrecta.","o":["Podrá dictar reglamentos sobre su propio funcionamiento y organización, que podrán ser aprobados por cualquiera de las Salas del Tribunal.","El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","Cuando el Tribunal Constitucional anule un acto o resolución que contravenga la Jurisdicción lo ha de hacer motivadamente y previa audiencia al Ministerio Fiscal y al órgano autor del acto o resolución.","El Tribunal en Pleno elige de entre sus miembros por votación secreta a su Presidente y propone al Rey su nombramiento."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Podrá dictar reglamentos sobre su propio funcionamiento y organización, que podrán ser aprobados por cualquiera de las Salas del Tribunal</mark></span>El <span class=\"ref-norma\">art. 2.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Estos reglamentos, que deberán ser aprobados por el Tribunal en Pleno, se publicarán en el «Boletín Oficial del Estado», autorizados por su Presidente.\"</span>. Los reglamentos los aprueba el Pleno, no «cualquiera de las Salas»."},{"i":"7-ia-7006","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Atribuciones del Tribunal Constitucional. El Tribunal Constitucional conoce de los conflictos en defensa de la autonomía local, que se enuncian en la Ley como:","o":["una modalidad de conflicto constitucional de competencia entre Comunidades Autónomas.","una modalidad del recurso de amparo.","una competencia del Pleno excluida de las Salas.","una atribución propia, distinta de los conflictos entre órganos constitucionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">una atribución propia, distinta de los conflictos entre órganos constitucionales</mark></span>El <span class=\"ref-norma\">art. 2.1.d bis de LOTC</span> dispone: <span class=\"ref-concepto\">\"d) bis. De los conflictos en defensa de la autonomía local\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — Cuestiones prejudiciales e incidentales","q":[{"i":"7-135","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La competencia del Tribunal Constitucional se extiende:","o":["Al conocimiento y decisión de las cuestiones prejudiciales o incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta.","Al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta.","Al conocimiento y decisión de las cuestiones no prejudiciales o incidentales pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento inconstitucional de ésta.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta</mark></span>El <span class=\"ref-norma\">art. 3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce, a los solos efectos del enjuiciamiento constitucional de ésta.\"</span>. La conjunción literal es «prejudiciales e incidentales» (no «o»)."},{"i":"7-ia-7011","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Cuestiones prejudiciales e incidentales. La competencia del Tribunal Constitucional se extiende al conocimiento y decisión de las cuestiones prejudiciales e incidentales no pertenecientes al orden constitucional, directamente relacionadas con la materia de que conoce:","o":["con carácter vinculante para los órganos de la jurisdicción ordinaria.","cuando lo solicite el Ministerio Fiscal.","a los solos efectos del enjuiciamiento constitucional de ésta.","siempre que no exista pronunciamiento del Tribunal Supremo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">a los solos efectos del enjuiciamiento constitucional de ésta</mark></span>El <span class=\"ref-norma\">art. 3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a los solos efectos del\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5 — Composición R2","q":[{"i":"7-11","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional está integrado por _______ con el título de Magistrados del Tribunal Constitucional.","o":["Ocho miembros.","Diez miembros.","Doce miembros.","Catorce miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Doce miembros</mark></span>El <span class=\"ref-norma\">art. 5 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional está integrado por doce miembros, con el título de Magistrados del Tribunal Constitucional.\"</span>."}]},{"a":"Artículo 6 — Pleno, Sala y Sección ✱ R3","q":[{"i":"7-98","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿A quién darán cuenta las Secciones sobre las propuestas de admisión o inadmisión de los asuntos de su competencia?","o":["A la Sala Primera.","A las Salas.","Al Pleno.","A la Sala Segunda."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Pleno</mark></span>Según el <span class=\"ref-norma\">art. 8.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Se dará cuenta al Pleno de las propuestas de admisión o inadmisión de asuntos de su competencia\"</span> (verificado con el texto del temario)."},{"i":"7-30","p":"Ley Orgánica del Tribunal Constitucional. En cuanto a los recursos de amparo, indique cuál de los siguientes tiene capacidad para adoptar medidas cautelares y resoluciones provisionales:","o":["La Sala.","El Ministerio Fiscal y la Sección.","El Ministerio Fiscal y la Sala o la Sección.","La Sala o la Sección."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La Sala o la Sección</mark></span>El <span class=\"ref-norma\">art. 56.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala o la Sección podrá adoptar cualesquiera medidas cautelares y resoluciones provisionales previstas en el ordenamiento, que, por su naturaleza, puedan aplicarse en el proceso de amparo y tiendan a evitar que el recurso pierda su finalidad.\"</span>."},{"i":"7-70","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De su organización y atribuciones. El Tribunal Constitucional actúa en: señale la INCORRECTA.","o":["Gran Sala.","Sección.","Pleno.","Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Gran Sala</mark></span>El <span class=\"ref-norma\">art. 6.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección.\"</span>."},{"i":"7-106","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional actúa en: señale la INCORRECTA.","o":["Pleno.","Gran Sala.","Sala.","Sección."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Gran Sala</mark></span>El <span class=\"ref-norma\">art. 6.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección.\"</span>."},{"i":"7-117","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional, su organización y atribuciones. El Tribunal Constitucional actúa en: señale la INCORRECTA.","o":["Gran Sala.","Sección.","Pleno.","Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Gran Sala</mark></span>No existe la «Gran Sala». Según el <span class=\"ref-norma\">art. 6.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7017","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Organización. El Tribunal Constitucional actúa:","o":["en Pleno, en Sala o en Sección.","en Pleno o en Sala exclusivamente.","en Pleno, en Comisión o en Sección.","en Sala o en Sección exclusivamente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en Pleno, en Sala o en Sección</mark></span>El <span class=\"ref-norma\">art. 6.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional actúa en Pleno, en Sala o en Sección\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7018","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Organización. El Pleno está integrado por todos los Magistrados del Tribunal. Lo preside el Presidente y, en su defecto:","o":["el Magistrado de mayor edad, y a falta de este, el más antiguo.","el Vicepresidente y, a falta de ambos, el Magistrado de menor edad.","el Presidente de la Sala Primera y, a falta de este, el de la Sala Segunda, en los términos que establezca el propio Reglamento.","el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad</mark></span>El <span class=\"ref-norma\">art. 6.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Lo preside el Presidente del Tribunal y, en su defecto, el Vicepresidente y, a falta de ambos, el Magistrado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-45","p":"Ley Orgánica del Tribunal Constitucional. ¿Quién preside el Pleno del Tribunal Constitucional en ausencia del Presidente y el Vicepresidente, cuando todos hubiesen sido nombrados al mismo tiempo en el cargo y tuvieren la misma antigüedad?","o":["El magistrado que antes hubiera iniciado la carrera judicial.","El magistrado que designe el Presidente, o en su defecto el Vicepresidente.","El magistrado de mayor edad.","El magistrado que designe el Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El magistrado de mayor edad</mark></span>El <span class=\"ref-norma\">art. 6.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Lo preside el Presidente del Tribunal y, en su defecto, el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad.\"</span>."},{"i":"7-99","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Quién preside el Pleno del Tribunal Constitucional en ausencia del Presidente y el Vicepresidente, cuando todos hubiesen sido nombrados al mismo tiempo en el cargo y tuvieren la misma antigüedad?","o":["El magistrado que antes hubiera iniciado la carrera judicial.","El magistrado que designe el Presidente, o en su defecto el Vicepresidente.","El magistrado de mayor edad.","El magistrado que designe el Consejo General del Poder Judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El magistrado de mayor edad</mark></span>Según el <span class=\"ref-norma\">art. 6.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Lo preside el Presidente del Tribunal y, en su defecto, el Vicepresidente y, a falta de ambos, el Magistrado más antiguo en el cargo y, en caso de igual antigüedad, el de mayor edad\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7020","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas. El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto:","o":["el Vicepresidente del Tribunal.","el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","el Magistrado de mayor edad, en todo caso, salvo que el Estado miembro afectado disponga otra cosa.","el Magistrado de menor edad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad</mark></span>El <span class=\"ref-norma\">art. 7.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Las Salas ✱","q":[{"i":"7-23","p":"Ley Orgánica del Tribunal Constitucional. El Tribunal Constitucional consta de:","o":["Dos salas.","Tres salas.","Cuatro salas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-60","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Por cuántas salas está compuesto el Tribunal Constitucional?","o":["Tres Salas.","Cuatro Salas.","Dos Salas.","Una única Sala."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Dos Salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-69","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional consta de Dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.","o":["Dos Salas.","Tres Salas.","Cuatro Salas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos Salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-115","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Tribunal Constitucional consta de _______ cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.","o":["Dos Salas.","Tres Salas.","Cuatro Salas.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Dos Salas</mark></span>El <span class=\"ref-norma\">art. 7.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno.\"</span>."},{"i":"7-ia-7327","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la captación, reproducción o publicación por fotografía, filme o cualquier otro procedimiento, de la imagen de una persona en lugares o momentos de su vida privada o fuera de ellos, salvo los casos previstos:","o":["en el artículo segundo, dos.","en el artículo noveno, dos.","en el artículo octavo, dos.","en el artículo octavo, uno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en el artículo octavo, dos</mark></span>El <span class=\"ref-norma\">art. 7.5 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"salvo los casos previstos en el artículo octavo, dos\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-111","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del Tribunal Constitucional, su organización y atribuciones. Señale la CORRECTA.","o":["El Tribunal Constitucional consta de tres Salas. Cada Sala está compuesta por siete Magistrados nombrados por el Tribunal en Pleno.","El Presidente del Tribunal lo es también de la Sala Primera, que presidirá, en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","El Vicepresidente del Tribunal presidirá en la Sala Segunda y, en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.","B y C son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">B y C son correctas</mark></span>El <span class=\"ref-norma\">art. 7 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno. Dos. El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad. Tres. El Vicepresidente del Tribunal presidirá en la Sala Segunda y, en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.\"</span>."},{"i":"7-ia-7019","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas. El Tribunal Constitucional consta de dos Salas. Cada Sala está compuesta por seis Magistrados:","o":["nombrados por el Presidente del Tribunal.","nombrados por el Rey, a propuesta del Pleno.","nombrados por el Tribunal en Pleno.","elegidos por las Cortes Generales."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">nombrados por el Tribunal en Pleno</mark></span>El <span class=\"ref-norma\">art. 7.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Cada Sala está compuesta por seis Magistrados nombrados por el Tribunal en Pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-26","p":"Ley Orgánica del Tribunal Constitucional. ¿Qué Salas presidirá el Presidente del Tribunal Constitucional?","o":["La Sala Primera.","La Sala Segunda.","La Sala Primera o la Sala Segunda.","La Sala Primera y la Sala Segunda."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala Primera</mark></span>La Sala Segunda la preside el Vicepresidente (art. 7.3). Según el <span class=\"ref-norma\">art. 7.2 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Presidente del Tribunal lo es también de la Sala Primera\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7021","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas. El Vicepresidente del Tribunal presidirá:","o":["la Sala Segunda.","la Sala Primera.","las Secciones del Pleno.","el Pleno en todo caso."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la Sala Segunda</mark></span>El <span class=\"ref-norma\">art. 7.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El Vicepresidente del Tribunal presidirá en la Sala Segunda\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 12 — Reparto de asuntos entre las Salas R4","q":[{"i":"7-75","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La distribución de asuntos entre las Salas del Tribunal se efectuará:","o":["Según un turno establecido por la Comisión.","A propuesta del Pleno.","Según un turno establecido por el Pleno a propuesta de su Presidente.","Según un turno establecido por el Presidente a propuesta del Pleno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Según un turno establecido por el Pleno a propuesta de su Presidente</mark></span>El <span class=\"ref-norma\">art. 12 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La distribución de asuntos entre las Salas del Tribunal se efectuará según un turno establecido por el Pleno a propuesta de su Presidente.\"</span>."}]},{"a":"Artículo 13 — Cambio de doctrina","q":[{"i":"7-59","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Cuando una Sala considere necesario apartarse en cualquier punto de la doctrina constitucional precedente sentada por el Tribunal: Señale la opción correcta.","o":["La cuestión se someterá a la decisión del Consejo General del Poder Judicial.","La cuestión se someterá a la decisión del Pleno.","La cuestión se someterá a la decisión de la Sala Primera.","La cuestión se someterá a la decisión del Consejo de Gobierno."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La cuestión se someterá a la decisión del Pleno</mark></span>El <span class=\"ref-norma\">art. 13 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Cuando una Sala considere necesario apartarse en cualquier punto de la doctrina constitucional precedente sentada por el Tribunal, la cuestión se someterá a la decisión del Pleno.\"</span>."},{"i":"7-ia-7036","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Doctrina constitucional. Cuando una Sala considere necesario apartarse en cualquier punto de la doctrina constitucional precedente sentada por el Tribunal, la cuestión se someterá:","o":["a la decisión de la otra Sala.","a la decisión del Pleno.","al informe del Presidente.","a la decisión de las Cámaras."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a la decisión del Pleno</mark></span>El <span class=\"ref-norma\">art. 13 de LOTC</span> dispone: <span class=\"ref-concepto\">\"la cuestión se someterá a la decisión del Pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-81","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las Salas del Tribunal Constitucional conocerán:","o":["De los asuntos que, atribuidos a la justicia constitucional, no sean de la competencia del Pleno.","De aquellas cuestiones que, habiendo sido atribuidas al conocimiento de las Secciones, quisiesen resolver la propia Sala.","De aquellas cuestiones necesarias para apartarse a cualquier punto de la doctrina constitucional precedente sentada por el Tribunal.","A y B son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 11 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las Salas del Tribunal Constitucional conocerán de los asuntos que, atribuidos a la justicia constitucional, no sean de la competencia del Pleno. Dos. También conocerán las Salas de aquellas cuestiones que, habiendo sido atribuidas al conocimiento de las Secciones, entiendan que por su importancia deba resolver la propia Sala.\"</span>. La opción C es falsa: apartarse de la doctrina constitucional precedente se somete al Pleno (art. 13), no lo resuelve la Sala."}]},{"a":"Artículo 15 — El Presidente del Tribunal","q":[{"i":"7-18","p":"Ley Orgánica del Tribunal Constitucional. Indique cuál de las siguientes funciones NO se atribuye al Presidente del Tribunal Constitucional:","o":["Preside las Salas.","Comunica al Consejo General del Poder Judicial las vacantes.","Nombra a los letrados.","Ejerce las potestades administrativas sobre el personal del Tribunal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Preside las Salas</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Tribunal lo es también de la Sala Primera, que presidirá en su defecto, el Magistrado más antiguo y, en caso de igual antigüedad, el de mayor edad.\"</span>. El Presidente solo preside la Sala Primera; la Segunda la preside el Vicepresidente (art. 7)."},{"i":"7-80","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente del Tribunal Constitucional: señale la INCORRECTA.","o":["Tiene la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas.","Adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones.","Nombra los secretarios de las Salas del Tribunal.","Nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral y ejercerá las potestades administrativas sobre el personal del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Nombra los secretarios de las Salas del Tribunal</mark></span>El <span class=\"ref-norma\">art. 15 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas; adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones; comunica a las Cámaras, al Gobierno o al Consejo General del Poder Judicial, en cada caso, las vacantes; nombra a los letrados, convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral, y ejerce las potestades administrativas sobre el personal del Tribunal.\"</span>. El art. 15 no atribuye al Presidente nombrar «secretarios de las Salas»: nombra a los letrados."},{"i":"7-91","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Cuál de las siguientes funciones se atribuyen al Presidente del Tribunal Constitucional?","o":["Preside el Tribunal en Pleno.","Adopta medidas precisas para el funcionamiento de las Salas.","Comunica al Gobierno las vacantes.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 15 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Tribunal en Pleno y convoca las Salas; adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones; comunica a las Cámaras, al Gobierno o al Consejo General del Poder Judicial, en cada caso, las vacantes; nombra a los letrados, convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral, y ejerce las potestades administrativas sobre el personal del Tribunal.\"</span>. Todas las funciones indicadas figuran en el art. 15."},{"i":"7-139","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente del Tribunal Constitucional: señale la INCORRECTA.","o":["Tiene la representación del Tribunal, convoca y preside el Pleno y convoca las Salas.","Adopta las medidas precisas para el funcionamiento del Tribunal, de las Salas y de las Secciones.","Autoriza con su firma los acuerdos del Tribunal en Pleno y de las Salas.","Nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral y ejercerá las potestades administrativas sobre el personal del Tribunal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Autoriza con su firma los acuerdos del Tribunal en Pleno y de las Salas</mark></span>Autorizar con su firma los acuerdos no figura entre las funciones del art. 15. Según el <span class=\"ref-norma\">art. 15 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El Presidente [...] nombra a los letrados, convoca los concursos para cubrir las plazas de funcionarios y los puestos de personal laboral, y ejerce las potestades administrativas sobre el personal del Tribunal\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7038","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El Presidente del Tribunal. El Presidente del Tribunal Constitucional ejerce la representación del Tribunal, convoca y preside el Pleno y convoca las Salas, y entre otras funciones:","o":["nombra a los Magistrados de cada Sala.","propone a los Magistrados al Rey.","convoca las Secciones y decide sobre su composición, conforme al procedimiento que se establezca reglamentariamente.","nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">nombra a los letrados y convoca los concursos para cubrir las plazas de funcionarios</mark></span>El <span class=\"ref-norma\">art. 15 de LOTC</span> dispone: <span class=\"ref-concepto\">\"nombra a los\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 42 — Actos sin valor de Ley de las Cortes y Asambleas","q":[{"i":"7-52","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Qué se requiere para proceder en vía de amparo constitucional contras las decisiones y actos sin valor de ley de las Cortes Generales que violen derecho y libertades susceptibles de amparo?","o":["Haber agotado la vía judicial procedente.","No haber transcurrido veinte días desde que sean firmes.","No haber transcurrido tres meses desde que sean firmes.","A y C son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No haber transcurrido tres meses desde que sean firmes</mark></span>Agotar la vía judicial es exigencia del art. 43 (Gobierno y autoridades), no del art. 42. Veinte días es el plazo del art. 43.2. Según el <span class=\"ref-norma\">art. 42 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las decisiones o actos sin valor de Ley, emanados de las Cortes o de cualquiera de sus órganos [...] podrán ser recurridos dentro del plazo de tres meses desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean firmes\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7162","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a decisiones de las Cortes y Asambleas. Las decisiones o actos sin valor de Ley, emanados de las Cortes o de las Asambleas legislativas de las Comunidades Autónomas, que violen los derechos susceptibles de amparo, podrán ser recurridos dentro del plazo de:","o":["veinte días desde su notificación, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","tres meses desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean firmes.","treinta días desde su publicación.","un mes desde que sean firmes."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres meses desde que, con arreglo a las normas internas de las Cámaras o Asambleas, sean firmes</mark></span>El <span class=\"ref-norma\">art. 42 de LOTC</span> dispone: <span class=\"ref-concepto\">\"podrán ser recurridos dentro del plazo de tres meses desde que, con arreglo a las normas internas de las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 44 · AMPARO FRENTE A ÓRGANOS JUDICIALES","q":[{"i":"7-8","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo Constitucional. De la Procedencia e Interposición del recurso de amparo Constitucional. Contra las violaciones de los derechos y libertades susceptibles de amparo Constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un Órgano Judicial, podrá interponerse recurso de amparo en el plazo de:","o":["20 días, a partir de la notificación de la resolución recaída en el proceso judicial.","20 días, a partir de la fecha de la resolución recaída en el proceso judicial.","30 días, a partir de la notificación de la resolución recaída en el proceso judicial.","15 días, a partir de la fecha de la resolución recaída en el proceso judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">30 días, a partir de la notificación de la resolución recaída en el proceso judicial</mark></span>El <span class=\"ref-norma\">art. 44.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo será de 30 días, a partir de la notificación de la resolución recaída en el proceso judicial.\"</span>."},{"i":"7-76","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial, podrán dar lugar a este recurso siempre que se cumplan los requisitos siguientes:","o":["Que se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial.","Que la violación del derecho o la libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquélla se produjo, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional.","Que se haya denunciado formalmente en el proceso, en el acto u oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>El <span class=\"ref-norma\">art. 44.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquellas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional. c) Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.\"</span>. El requisito dice que el TC no entrará a conocer de los hechos «en ningún caso»."},{"i":"7-129","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial, podrán dar lugar a este recurso siempre que se cumplan los requisitos siguientes:","o":["Que se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto, dentro de la vía judicial.","Que la violación del derecho o la libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquéllas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional.","Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiere lugar para ello.","Todas las opciones son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas las opciones son correctas</mark></span>El <span class=\"ref-norma\">art. 44.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"b) Que la violación del derecho o libertad sea imputable de modo inmediato y directo a una acción u omisión del órgano judicial con independencia de los hechos que dieron lugar al proceso en que aquellas se produjeron, acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional. c) Que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional tan pronto como, una vez conocida, hubiera lugar para ello.\"</span>."},{"i":"7-ia-7166","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. Las violaciones de derechos que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial podrán dar lugar al recurso siempre que se cumplan, entre otros, el requisito de que:","o":["se haya solicitado la nulidad de actuaciones ante el Tribunal Supremo en todo caso, salvo que el Estado miembro afectado disponga otra cosa.","se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial.","se haya recabado informe del Ministerio Fiscal.","se haya interpuesto recurso ante el Consejo General del Poder Judicial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se hayan agotado todos los medios de impugnación previstos por las normas procesales para el caso concreto dentro de la vía judicial</mark></span>El <span class=\"ref-norma\">art. 44.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Que se hayan agotado todos los medios de impugnación previstos por las normas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7167","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. La violación del derecho o libertad debe ser imputable de modo inmediato y directo a una acción u omisión del órgano judicial, con independencia de los hechos que dieron lugar al proceso, acerca de los que:","o":["en ningún caso entrará a conocer el Tribunal Constitucional.","solo entrará a conocer el Tribunal Constitucional cuando afecten a derechos fundamentales.","entrará a conocer el Tribunal Constitucional en trámite de admisión.","entrará a conocer el Pleno cuando lo solicite el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en ningún caso entrará a conocer el Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 44.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"acerca de los que, en ningún caso, entrará a conocer el Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7168","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. Entre los requisitos del amparo frente a órganos judiciales figura que se haya denunciado formalmente en el proceso, si hubo oportunidad, la vulneración del derecho constitucional:","o":["en el escrito de interposición del recurso de apelación, conforme al procedimiento que se establezca reglamentariamente.","en el plazo de cinco días desde su conocimiento.","ante el Ministerio Fiscal.","tan pronto como, una vez conocida, hubiera lugar para ello."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tan pronto como, una vez conocida, hubiera lugar para ello</mark></span>El <span class=\"ref-norma\">art. 44.1.c de LOTC</span> dispone: <span class=\"ref-concepto\">\"tan pronto como, una vez conocida, hubiera lugar\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7169","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. El plazo para interponer el recurso de amparo frente a actos u omisiones de órganos judiciales será de:","o":["20 días, a partir de la notificación de la resolución recaída en el proceso judicial, sin perjuicio de lo dispuesto en el Derecho nacional.","tres meses, a partir de la notificación de la resolución judicial.","30 días, a partir de la notificación de la resolución recaída en el proceso judicial.","15 días, a partir de la notificación de la resolución judicial."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">30 días, a partir de la notificación de la resolución recaída en el proceso judicial</mark></span>El <span class=\"ref-norma\">art. 44.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo será de 30 días, a partir de la\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7202","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Amparo frente a actos u omisiones de órganos judiciales. Señale la INCORRECTA sobre el amparo frente a actos u omisiones de órganos judiciales:","o":["El plazo para interponerlo es de treinta días desde la notificación de la resolución judicial.","El plazo para interponerlo es de veinte días.","Hay que haber agotado todos los medios de impugnación de la vía judicial.","El Tribunal Constitucional nunca entra a conocer de los hechos del proceso."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El plazo para interponerlo es de veinte días</mark></span>El <span class=\"ref-norma\">art. 44 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"El plazo para interponer el recurso de amparo será de 30 días, a partir de la\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 46.1 · ESTÁN LEGITIMADOS PARA INTERPONER EL RECURSO DE AMPARO CONSTITUCIONAL","q":[{"i":"7-147","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. En los casos de decisiones o actos sin valor de Ley emanados de las Cortes o de las Asambleas legislativas de las Comunidades Autónomas, están legitimados para interponer el recurso de amparo constitucional:","o":["La persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal.","Quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal.","La persona directamente afectada y el Ministerio Fiscal.","Cincuenta Diputados o cincuenta Senadores."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 46.1.a) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"a) En los casos de los artículos cuarenta y dos y cuarenta y cinco, la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-ia-7170","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación en el amparo. En los casos de amparo frente a decisiones de las Cortes o Asambleas, están legitimados para interponer el recurso:","o":["quienes hayan sido parte en el proceso judicial, el Defensor del Pueblo y el Ministerio Fiscal.","la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal.","el Presidente del Gobierno y cincuenta Diputados.","la persona directamente afectada y el Abogado del Estado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 46.1.a de LOTC</span> dispone: <span class=\"ref-concepto\">\"la persona directamente afectada, el Defensor del Pueblo y el Ministerio Fiscal\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7171","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación en el amparo. En los casos de amparo frente a actos del Gobierno o de órganos judiciales, están legitimados:","o":["quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal.","la persona directamente afectada y el Ministerio Fiscal exclusivamente, en los términos que establezca el propio Reglamento.","cualquier ciudadano con interés legítimo.","las asociaciones de consumidores y usuarios."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 46.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7172","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Legitimación en el amparo. Si el recurso de amparo se promueve por el Defensor del Pueblo o el Ministerio Fiscal, la Sala competente lo comunicará a los posibles agraviados conocidos y ordenará anunciar la interposición del recurso en el «Boletín Oficial del Estado». Dicha publicación:","o":["se realizará en el plazo de quince días.","tendrá carácter reservado.","sustituirá la notificación a los agraviados.","tendrá carácter preferente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tendrá carácter preferente</mark></span>El <span class=\"ref-norma\">art. 46.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"Dicha publicación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 46 — Legitimación para el amparo ✱","q":[{"i":"7-54","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. Admitida la demanda de amparo, una vez se reciban los requerimientos oportunos y haya transcurrido el tiempo de emplazamiento, la Sala dará vista de las mismas a: Señale la opción incorrecta.","o":["El Abogado del Estado.","La Administración Pública, si estuviera interesada.","El Defensor del Pueblo.","El Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Defensor del Pueblo</mark></span>El <span class=\"ref-norma\">art. 52.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sala dará vista de las mismas a quien promovió el amparo, a los personados en el proceso, al Abogado del Estado, si estuviera interesada la Administración Pública, y al Ministerio Fiscal. La vista será por plazo común que no podrá exceder de veinte días, y durante él podrán presentarse las alegaciones procedentes.\"</span>."},{"i":"7-126","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Quién intervendrá en todos los procesos de amparo, en defensa de la legalidad de los derechos de los ciudadanos y del interés público tutelado por la Ley?","o":["El Ministerio Fiscal.","El Fiscal General del Estado.","El Defensor del Pueblo.","El Ministerio de Justicia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 47.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El Ministerio Fiscal intervendrá en todos los procesos de amparo, en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la Ley.\"</span>."},{"i":"7-31","p":"Ley Orgánica del Tribunal Constitucional. Están legitimados para interponer el recurso de amparo constitucional por las violaciones de los derechos y libertades susceptibles de amparo constitucional, que tuvieran su origen inmediato y directo en un acto u omisión de un órgano judicial. Señale la respuesta incorrecta.","o":["El Ministerio Fiscal.","El Consejo de Ministros.","El Defensor del Pueblo.","Quienes hayan sido parte en el proceso judicial correspondiente."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo de Ministros</mark></span>El <span class=\"ref-norma\">art. 46.1.b) de la LOTC</span> dispone: <span class=\"ref-concepto\">\"En los casos de los artículos cuarenta y tres y cuarenta y cuatro, quienes hayan sido parte en el proceso judicial correspondiente, el Defensor del Pueblo y el Ministerio Fiscal.\"</span>."}]},{"a":"Artículo 48 — Órganos competentes R6","q":[{"i":"7-67","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. El conocimiento de los recursos de amparo constitucional corresponde a:","o":["Las Salas del Tribunal Constitucional y, en su caso, a las Secciones.","El Pleno, entre otros.","Las Salas del Tribunal Constitucional, exclusivamente.","Las respuestas A y B son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las Salas del Tribunal Constitucional y, en su caso, a las Secciones</mark></span>No es «exclusivamente» de las Salas: también las Secciones, en su caso. Según el <span class=\"ref-norma\">art. 48 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El conocimiento de los recursos de amparo constitucional corresponde a las Salas del Tribunal Constitucional y, en su caso, a las Secciones\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7186","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Vista en el amparo. Presentadas las alegaciones, la Sala podrá deferir la resolución del recurso, cuando para su resolución sea aplicable doctrina consolidada del Tribunal Constitucional:","o":["al Pleno.","a una de sus Secciones.","a la otra Sala.","al Presidente del Tribunal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">a una de sus Secciones</mark></span>El <span class=\"ref-norma\">art. 52.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"cuando para su resolución sea aplicable doctrina consolidada del Tribunal Constitucional, a una de sus Secciones\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 49 — La demanda","q":[{"i":"7-38","p":"Ley Orgánica del Tribunal Constitucional. El recurso de amparo se iniciará mediante: Señale la opción correcta.","o":["Demanda.","Demanda o querella.","Tesis.","Demanda, querella o de oficio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Demanda</mark></span>No existe querella ni inicio de oficio. Según el <span class=\"ref-norma\">art. 49.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten\"</span> (verificado con el texto del temario)."},{"i":"7-73","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo. El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado.","o":["Sentencia.","Querella.","Demanda.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Demanda</mark></span>El <span class=\"ref-norma\">art. 49.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado. En todo caso, la demanda justificará la especial trascendencia constitucional del recurso.\"</span>."},{"i":"7-125","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos amparo Constitucional. El recurso de amparo constitucional se iniciará mediante _______ en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considera vulnerado.","o":["Sentencia.","Querella.","Demanda.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Demanda</mark></span>El <span class=\"ref-norma\">art. 49.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado. En todo caso, la demanda justificará la especial trascendencia constitucional del recurso.\"</span>."},{"i":"7-29","p":"Ley Orgánica del Tribunal Constitucional. ¿Cuál es un requisito en todo caso para la admisión de un recurso de amparo constitucional?","o":["La especial relevancia para la jurisprudencia.","La especial trascendencia constitucional del recurso.","La especial necesidad de cumplir lo preceptuado en la Constitución.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La especial trascendencia constitucional del recurso</mark></span>El <span class=\"ref-norma\">art. 49.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"El recurso de amparo constitucional se iniciará mediante demanda en la que se expondrán con claridad y concisión los hechos que la fundamenten, se citarán los preceptos constitucionales que se estimen infringidos y se fijará con precisión el amparo que se solicita para preservar o restablecer el derecho o libertad que se considere vulnerado. En todo caso, la demanda justificará la especial trascendencia constitucional del recurso.\"</span>."},{"i":"7-ia-7176","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Demanda de amparo. La demanda de amparo justificará, en todo caso:","o":["la urgencia excepcional del recurso.","el agotamiento de la vía administrativa, salvo que el Estado miembro afectado disponga otra cosa.","la cuantía del perjuicio sufrido.","la especial trascendencia constitucional del recurso."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la especial trascendencia constitucional del recurso</mark></span>El <span class=\"ref-norma\">art. 49.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En todo caso, la demanda justificará la especial trascendencia constitucional del recurso\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7177","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Demanda de amparo. Con la demanda de amparo se acompañarán el documento que acredite la representación del solicitante y:","o":["el informe del Ministerio Fiscal.","el dictamen del Defensor del Pueblo.","en su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.","la acreditación del pago de las tasas, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">en su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo</mark></span>El <span class=\"ref-norma\">art. 49.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En su caso, la copia, traslado o certificación de la resolución recaída en el\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-68","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo Constitucional. Con la demanda se acompañarán:","o":["El documento que acredite la representación del solicitante del amparo.","En su caso, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.","Tanta copias literales de la misma y de los documentos presentados como partes en el previo proceso, si la hubiere, y una más para el Ministerio Fiscal.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 49.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Con la demanda se acompañarán: a) El documento que acredite la representación del solicitante del amparo. b) En su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.\"</span>."},{"i":"7-113","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo Constitucional. Con la demanda se acompañarán:","o":["El documento que acredita la representación del solicitante del amparo.","En su caso, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.","Tanto copias literales de la misma y de los documentos presentados como partes en el previo proceso, si la hubiere, y una más para el Ministerio Fiscal.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 49.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Con la demanda se acompañarán: a) El documento que acredite la representación del solicitante del amparo. b) En su caso, la copia, traslado o certificación de la resolución recaída en el procedimiento judicial o administrativo.\"</span>."},{"i":"7-ia-7178","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Demanda de amparo. De incumplirse los requisitos de la demanda de amparo, las Secretarías de Justicia lo pondrán de manifiesto al interesado en el plazo de:","o":["5 días, con el apercibimiento de que se archivará el recurso.","10 días, con el apercibimiento de que, de no subsanarse el defecto, se acordará la inadmisión del recurso.","15 días, con el apercibimiento de que se acordará la inadmisión, en los términos que establezca el propio Reglamento.","3 días, con el apercibimiento de que se tendrá por desistido."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">10 días, con el apercibimiento de que, de no subsanarse el defecto, se acordará la inadmisión del recurso</mark></span>El <span class=\"ref-norma\">art. 49.4 de LOTC</span> dispone: <span class=\"ref-concepto\">\"las Secretarías de Justicia lo pondrán de manifiesto al interesado en el plazo de\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 50 — Admisión a trámite ✱","q":[{"i":"7-33","p":"Ley Orgánica del Tribunal Constitucional. El recurso de amparo debe ser objeto de una decisión de admisión a trámite. La Sección, por _______ de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso solamente cuando concurran todos los siguientes requisitos.","o":["Mayoría simple.","Unanimidad.","Mayoría de dos tercios.","Mayoría cualificada de tres cuartos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Unanimidad</mark></span>Si hay mayoría pero no unanimidad, la Sección traslada la decisión a la Sala (art. 50.2). Según el <span class=\"ref-norma\">art. 50.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso solamente cuando concurran todos los siguientes requisitos\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7179","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. La Sección acordará mediante providencia la admisión, en todo o en parte, del recurso de amparo solamente cuando concurran todos los requisitos legales y lo decida:","o":["por unanimidad de sus miembros.","por mayoría de sus miembros.","por mayoría de dos tercios.","por decisión del Presidente de la Sección."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por unanimidad de sus miembros</mark></span>El <span class=\"ref-norma\">art. 50.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-94","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. ¿Mediante qué tipo de resolución se podrá admitir o inadmitir un recurso de amparo?","o":["Auto.","Decreto.","Providencia.","Sentencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Providencia</mark></span>La inadmisión también es por providencia (art. 50.3); el recurso de súplica se resuelve mediante auto. Según el <span class=\"ref-norma\">art. 50.1 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión, en todo o en parte, del recurso\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7180","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Para admitir a trámite el recurso de amparo, el contenido del recurso debe justificar una decisión sobre el fondo en razón de su especial trascendencia constitucional, que se apreciará atendiendo a:","o":["la gravedad del perjuicio sufrido por el recurrente.","la existencia de doctrina contradictoria entre las Salas.","la relevancia social de los hechos que dieron lugar al recurso, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","su importancia para la interpretación de la Constitución, para su aplicación o para su general eficacia, y para la determinación del contenido y alcance de los derechos fundamentales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">su importancia para la interpretación de la Constitución, para su aplicación o para su general eficacia, y para la determinación del contenido y alcance de los derechos fundamentales</mark></span>El <span class=\"ref-norma\">art. 50.1.b de LOTC</span> dispone: <span class=\"ref-concepto\">\"que se apreciará atendiendo a su importancia para la interpretación de la Constitución, para su\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-148","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. Cuando la admisión a trámite del recurso de amparo, aun habiendo obtenido la mayoría, no alcance la unanimidad:","o":["La Sección acordará la inadmisión mediante providencia.","La Sección elevará la decisión al Pleno para su resolución.","La Sección trasladará la decisión a la Sala respectiva para su resolución.","Se entenderá admitido a trámite el recurso."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La Sección trasladará la decisión a la Sala respectiva para su resolución</mark></span>El <span class=\"ref-norma\">art. 50.2 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Cuando la admisión a trámite, aun habiendo obtenido la mayoría, no alcance la unanimidad, la Sección trasladará la decisión a la Sala respectiva para su resolución.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-ia-7181","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Cuando la admisión a trámite, aun habiendo obtenido la mayoría, no alcance la unanimidad en la Sección:","o":["se archivará el recurso.","decidirá el Presidente de la Sección con voto de calidad, sin perjuicio de lo dispuesto en el Derecho nacional.","la Sección trasladará la decisión a la Sala respectiva para su resolución.","se elevará la cuestión al Pleno."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Sección trasladará la decisión a la Sala respectiva para su resolución</mark></span>El <span class=\"ref-norma\">art. 50.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"la Sección trasladará la decisión a la Sala respectiva para su resolución\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-22","p":"Ley Orgánica del Tribunal Constitucional. Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán a: Señale la opción correcta.","o":["El demandante y el Ministerio Fiscal.","El demandante.","El demandante, el Ministerio Fiscal y el Defensor del Pueblo.","Quienes hayan sido parte en el proceso judicial correspondiente."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El demandante y el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal. Dichas providencias solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días. Este recurso se resolverá mediante auto, que no será susceptible de impugnación alguna.\"</span>."},{"i":"7-32","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Las providencias de inadmisión, adoptadas por las Secciones o las Salas, solamente podrán ser recurridas:","o":["En súplica por el Ministerio Fiscal en el plazo de tres días.","En súplica por el Ministerio Fiscal en el plazo de cinco días.","En súplica por el Pleno en el plazo de tres días.","En súplica por el Pleno en el plazo de cinco días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">En súplica por el Ministerio Fiscal en el plazo de tres días.</mark></span> El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, [...] solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días.\"</span> TEST 3"},{"i":"7-88","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la tramitación de los recursos de amparo Constitucional. Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán:","o":["Al demandante.","Al Ministerio Fiscal.","A y B son correctas.","Ninguna es correcta."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>Según el <span class=\"ref-norma\">art. 50.3 de la LO 2/1979 (LOTC)</span>: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7203","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Señale la INCORRECTA sobre la admisión a trámite del recurso de amparo:","o":["La Sección admite el recurso por mayoría simple de sus miembros.","La admisión se acuerda mediante providencia.","Exige especial trascendencia constitucional.","Las providencias de inadmisión solo pueden ser recurridas en súplica por el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sección admite el recurso por mayoría simple de sus miembros</mark></span>El <span class=\"ref-norma\">art. 50 (señale la incorrecta) de LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sección, por unanimidad de sus miembros, acordará mediante providencia la admisión\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-55","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿En qué plazo podrá el Ministerio Fiscal interponer un recurso ante la inadmisión a trámite de un recurso de amparo?","o":["Cinco días.","Tres días.","Siete días.","Diez días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Tres días</mark></span>El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal. Dichas providencias solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días. Este recurso se resolverá mediante auto, que no será susceptible de impugnación alguna.\"</span>."},{"i":"7-ia-7182","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Admisión del recurso de amparo. Las providencias de inadmisión del recurso de amparo solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de:","o":["cinco días.","tres días.","diez días.","quince días."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">tres días</mark></span>El <span class=\"ref-norma\">art. 50.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-130","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Mediante qué tipo de resolución se resolverá el recurso de súplica interpuesto por el Ministerio Fiscal ante la inadmisión del recurso de amparo?","o":["Providencia.","Sentencia.","Auto.","Decreto."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Auto</mark></span>El <span class=\"ref-norma\">art. 50.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Las providencias de inadmisión, adoptadas por las Secciones o las Salas, especificarán el requisito incumplido y se notificarán al demandante y al Ministerio Fiscal. Dichas providencias solamente podrán ser recurridas en súplica por el Ministerio Fiscal en el plazo de tres días. Este recurso se resolverá mediante auto, que no será susceptible de impugnación alguna.\"</span>."}]},{"a":"Artículo 53 — Fallos R7","q":[{"i":"7-149","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Del recurso de amparo constitucional. La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos:","o":["Estimación o desestimación del amparo.","Otorgamiento de amparo o denegación de amparo.","Admisión o inadmisión del amparo.","Nulidad o confirmación del acto impugnado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Otorgamiento de amparo o denegación de amparo</mark></span>El <span class=\"ref-norma\">art. 53 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos: a) Otorgamiento de amparo. b) Denegación de amparo.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado EXOF · R7 en tu temario)</em>"}]},{"a":"ARTS. 53 Y 55.1 · FALLOS Y PRONUNCIAMIENTOS DE LA SENTENCIA DE AMPARO","q":[{"i":"7-64","p":"Ley Orgánica 2/1979, del Tribunal Constitucional. ¿Cuál de los siguientes se deberá pronunciar mediante sentencia en la resolución de los recursos de amparo?","o":["La Sala o, en su caso, la Sección.","El Pleno o, en su caso, la Sala o la Sección.","La Sección.","El Pleno o, en su caso, la Sala."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La Sala o, en su caso, la Sección</mark></span>El <span class=\"ref-norma\">art. 53 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos: a) Otorgamiento de amparo. b) Denegación de amparo.\"</span>."},{"i":"7-ia-7188","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Resolución del amparo. La Sala o, en su caso, la Sección, al conocer del fondo del asunto, pronunciará en su sentencia alguno de estos fallos:","o":["estimación, desestimación o inadmisión del amparo.","otorgamiento de amparo, denegación de amparo o archivo.","otorgamiento de amparo o remisión al Pleno.","otorgamiento de amparo o denegación de amparo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">otorgamiento de amparo o denegación de amparo</mark></span>El <span class=\"ref-norma\">art. 53 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) Otorgamiento de amparo. b) Denegación de amparo\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 55 — Contenido de la sentencia de amparo ✱","q":[{"i":"7-44","p":"Ley Orgánica del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: señale la incorrecta.","o":["Establecimiento de una indemnización a favor del recurrente por el perjuicio ocasionado por la vulneración del derecho objeto de amparo.","Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos y libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","Reconocimiento del derecho o libertad pública.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Establecimiento de una indemnización a favor del recurrente por el perjuicio ocasionado por la vulneración del derecho objeto de amparo</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-15","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","El reconocimiento del derecho o de las libertades públicas, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-110","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. De la resolución de los recursos de amparo constitucional y sus efectos. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["Declaración de nulidad de la decisión, acto o resolución que hayan impedido o pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-114","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["Declaración de nulidad de la decisión, acto o resolución que hayan impedido o pleno ejercicio de los derechos o libertades protegidos.","Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-ia-7190","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia de amparo. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes:","o":["declaración de nulidad de la norma aplicada, indemnización y restablecimiento del recurrente, conforme al procedimiento que se establezca reglamentariamente, sin perjuicio de lo dispuesto en el Derecho nacional.","declaración de nulidad de la decisión, acto o resolución, reconocimiento del derecho o libertad, y restablecimiento del recurrente en la integridad de su derecho.","reconocimiento del derecho, indemnización de daños y declaración de nulidad de la decisión.","declaración de inconstitucionalidad de la norma, nulidad del acto y condena en costas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">declaración de nulidad de la decisión, acto o resolución, reconocimiento del derecho o libertad, y restablecimiento del recurrente en la integridad de su derecho</mark></span>El <span class=\"ref-norma\">art. 55.1 de LOTC</span> dispone: <span class=\"ref-concepto\">\"a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-28","p":"Ley Orgánica del Tribunal Constitucional. La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: señale la incorrecta.","o":["Reconocimiento de los derechos a las libertades y dependientes de recurrente, salvo a oposición del recurrente.","Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos.","Reconocimiento del derecho o libertas públicas, de conformidad con su contenido constitucionalmente declarado.","Restablecimiento del recurrente en la integridad de sus derechos o libertas con la adopción de las medidas apropiadas, en su caso, para su conservación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Reconocimiento de los derechos a las libertades y dependientes de recurrente, salvo a oposición del recurrente</mark></span>El <span class=\"ref-norma\">art. 55.1 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"La sentencia que otorgue el amparo contendrá alguno o algunos de los pronunciamientos siguientes: a) Declaración de nulidad de la decisión, acto o resolución que hayan impedido el pleno ejercicio de los derechos o libertades protegidos, con determinación, en su caso, de la extensión de sus efectos. b) Reconocimiento del derecho o libertad pública, de conformidad con su contenido constitucionalmente declarado. c) Restablecimiento del recurrente en la integridad de su derecho o libertad con la adopción de las medidas apropiadas, en su caso, para su conservación.\"</span>."},{"i":"7-ia-7161","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Procedencia del recurso de amparo. En el amparo constitucional no pueden hacerse valer otras pretensiones que las dirigidas a:","o":["obtener una indemnización por los daños causados.","anular las normas aplicadas en la resolución impugnada.","restablecer o preservar los derechos o libertades por razón de los cuales se formuló el recurso.","depurar la responsabilidad disciplinaria de los funcionarios, en los términos que establezca el propio Reglamento."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">restablecer o preservar los derechos o libertades por razón de los cuales se formuló el recurso</mark></span>El <span class=\"ref-norma\">art. 41.3 de LOTC</span> dispone: <span class=\"ref-concepto\">\"En el amparo constitucional no pueden hacerse valer otras pretensiones que las\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7191","p":"Ley Orgánica 2/1979, de 3 de octubre, del Tribunal Constitucional. Sentencia de amparo. En el supuesto de que el recurso de amparo debiera ser estimado porque la ley aplicada lesione derechos fundamentales o libertades públicas, se elevará la cuestión:","o":["al Pleno, con suspensión del plazo para dictar sentencia.","al Pleno, sin suspensión del plazo para dictar sentencia.","a la otra Sala, con suspensión del plazo para dictar sentencia.","al Tribunal Supremo, con suspensión del plazo para dictar sentencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Pleno, con suspensión del plazo para dictar sentencia</mark></span>El <span class=\"ref-norma\">art. 55.2 de LOTC</span> dispone: <span class=\"ref-concepto\">\"se elevará la cuestión al Pleno con suspensión del plazo para dictar\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 1 — Objeto y carácter R10","q":[{"i":"7-ia-7307","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen, garantizado en la Constitución, será protegido civilmente frente a:","o":["las intromisiones ilegítimas de los poderes públicos exclusivamente, conforme al procedimiento que se establezca reglamentariamente.","las intromisiones ilegítimas que constituyan delito.","todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica.","las intromisiones ilegítimas de los medios de comunicación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica</mark></span>El <span class=\"ref-norma\">art. 1.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"será protegido civilmente frente a todo género de intromisiones ilegítimas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-1","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Disposiciones Generales. El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial.","o":["El derecho fundamental al honor, a la intimidad personal y familiar y a la propia imagen será protegido civilmente frente a todo género de intromisiones ilegítimas, de acuerdo con lo establecido en la presente Ley Orgánica.","El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible.","El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial</mark></span>El <span class=\"ref-norma\">art. 1.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial previsto en el artículo 9.º de esta Ley.\"</span>."},{"i":"7-ia-7308","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. El carácter delictivo de la intromisión no impedirá el recurso al procedimiento de tutela judicial previsto en la Ley. En cualquier caso, serán aplicables los criterios de esta Ley:","o":["para la determinación de la pena aplicable.","para la determinación de la responsabilidad civil derivada de delito.","para la determinación de la competencia judicial, sin perjuicio de lo dispuesto en el Derecho nacional.","para la determinación del plazo de prescripción."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">para la determinación de la responsabilidad civil derivada de delito</mark></span>El <span class=\"ref-norma\">art. 1.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"serán aplicables los\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-84","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El derecho al honor, a la intimidad personal y familiar y a la propia imagen es: señale la INCORRECTA.","o":["Irrenunciable.","Imprescriptible.","Inalienable.","Inembargable."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Inembargable</mark></span>«Inembargable» no figura en el texto: es la falsa. Según el <span class=\"ref-norma\">art. 1.3 de la LO 1/1982</span>: <span class=\"ref-concepto\">\"El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible\"</span> (verificado con el texto del temario)."},{"i":"7-128","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El derecho al honor, a la intimidad personal y familiar y a la propia imagen es:","o":["Irrenunciable.","Inalienable.","Imprescriptible.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 1.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El derecho al honor, a la intimidad personal y familiar y a la propia imagen es irrenunciable, inalienable e imprescriptible.\"</span>."},{"i":"7-ia-7309","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. El derecho al honor, a la intimidad personal y familiar y a la propia imagen es:","o":["irrenunciable, inalienable e imprescriptible.","irrenunciable, transmisible e imprescriptible.","renunciable, inalienable e imprescriptible.","irrenunciable, inalienable y prescriptible a los cuatro años."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">irrenunciable, inalienable e imprescriptible</mark></span>El <span class=\"ref-norma\">art. 1.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"es irrenunciable, inalienable e imprescriptible\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-61","p":"Ley Orgánica 1/1982, sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. En relación a los derechos al honor, a la intimidad personal y familiar y a la propia imagen, ¿Cuál tendrá una aplicación preferente, la protección penal o la civil?","o":["La protección civil.","La protección penal.","Se resolverán de forma independiente.","Se resolverá de forma conjunta, con preferencia sobre la protección civil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La protección penal</mark></span>Ojo: el art. 1.2 añade que el carácter delictivo no impide acudir a la tutela civil del art. 9. Según el <span class=\"ref-norma\">Preámbulo de la LO 1/1982</span>: <span class=\"ref-concepto\">\"en los casos que exista la protección penal tendrá ésta preferente aplicación, por ser sin duda la de más fuerte efectividad, si bien la responsabilidad civil derivada del delito se deberá fijar de acuerdo con los criterios que esta ley establece\"</span> (verificado con el texto del temario)."},{"i":"7-ia-7310","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Disposiciones generales. La renuncia a la protección prevista en la Ley será nula, sin perjuicio de:","o":["los supuestos de autorización judicial, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","los supuestos de interés público.","los supuestos de consentimiento tácito.","los supuestos de autorización o consentimiento a que se refiere el artículo segundo de la Ley."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los supuestos de autorización o consentimiento a que se refiere el artículo segundo de la Ley</mark></span>El <span class=\"ref-norma\">art. 1.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La renuncia a la protección prevista en esta ley será nula, sin perjuicio de los supuestos de autorización o consentimiento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 3 — Consentimiento de menores e incapaces ✱ R11","q":[{"i":"7-62","p":"Ley Orgánica 1/1982, sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. ¿De qué forma otorgarán el consentimiento los menores e incapaces cuando no dispongan suficientes condiciones de madurez?","o":["Mediante verba del Tribunal competente.","Mediante autorización expresa en presencia de su tutor, curador o defensor.","Mediante escrito por su representante legal.","Mediante anuencia del Ministerio Fiscal."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Mediante escrito por su representante legal</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-ia-7306","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo, en el caso de la lesión producida antes del fallecimiento sin que el titular ejerciera las acciones, estas solo subsistirán:","o":["si lo solicita el cónyuge supérstite.","si no han transcurrido ochenta años.","si el Ministerio Fiscal lo estima conveniente, salvo que el Estado miembro afectado disponga otra cosa.","si no hubieran podido ser ejercitadas por aquél o por su representante legal."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">si no hubieran podido ser ejercitadas por aquél o por su representante legal</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"sólo subsistirán éstas si no hubieran podido ser ejercitadas por aquél o por su representante legal\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-6","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. El consentimiento de los menores e incapaces deberá prestarse por ellos mismos si sus condiciones de madurez lo permiten, de acuerdo con la legislación civil. En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de _______ el Ministerio Fiscal se opusiere, resolverá el juez.","o":["Cinco días","Siete días","Ocho días","Diez días"],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ocho días</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-100","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. El consentimiento de los menores e incapaces; en los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si el Ministerio Fiscal se opusiere, resolverá el juez, en el plazo de:","o":["Cinco días.","Seis días.","Siete días.","Ocho días."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Ocho días</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-105","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. ¿Qué plazo tendrá el Ministerio Fiscal para oponerse al consentimiento de menores e incapaces otorgado mediante escrito de su representante?","o":["Ocho días.","Siete días.","Diez días.","Quince días."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ocho días</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-134","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. ¿Qué ocurrirá si el Ministerio Fiscal se opone al consentimiento de menores e incapaces otorgado mediante escrito por su representante legal?","o":["Que dicho consentimiento quedará invalidado.","Que resolverá el Juez.","Que deberá personarse tanto el menor o incapaz como su representante legal en audiencia ante el Ministerio Fiscal.","Nada, pues la oposición del Ministerio Fiscal no produce efectos sobre la autorización otorgada por representante legal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Que resolverá el Juez</mark></span>El <span class=\"ref-norma\">art. 3.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los restantes casos, el consentimiento habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez.\"</span>."},{"i":"7-ia-7316","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Consentimiento de menores e incapaces. En los restantes casos, el consentimiento de menores e incapaces habrá de otorgarse mediante escrito por su representante legal, quien estará obligado a poner en conocimiento previo del Ministerio Fiscal el consentimiento proyectado. Si en el plazo de ocho días el Ministerio Fiscal se opusiere:","o":["quedará sin efecto el consentimiento.","resolverá el Juez.","resolverá la autoridad administrativa competente.","se entenderá denegado el consentimiento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">resolverá el Juez</mark></span>El <span class=\"ref-norma\">art. 3.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Si en el plazo de ocho días el Ministerio Fiscal se opusiere, resolverá el Juez\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 4 — Acciones de protección de una persona fallecida ✱","q":[{"i":"7-92","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde:","o":["A quien esta haya designado a tal efecto en su testamento.","Al cónyuge.","Los ascendientes.","Los descendientes."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">A quien esta haya designado a tal efecto en su testamento</mark></span>El <span class=\"ref-norma\">art. 4.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien ésta haya designado a tal efecto en su testamento. La designación puede recaer en una persona jurídica.\"</span>. Solo en defecto de designación testamentaria (o fallecida la persona designada) están legitimados el cónyuge, descendientes, ascendientes y hermanos (art. 4.2)."},{"i":"7-ia-7305","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Preámbulo. Según el preámbulo, la protección en el caso de que la lesión se hubiera producido después del fallecimiento de una persona se atribuye, en primer lugar, a la persona que ésta hubiera designado:","o":["en su testamento.","en escritura pública notarial.","ante el Ministerio Fiscal.","en documento privado."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en su testamento</mark></span>El <span class=\"ref-norma\">preámbulo de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"de una persona a quien ésta hubiera designado en su testamento, en defecto de ella a los parientes supervivientes\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7317","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien ésta haya designado a tal efecto en su testamento. La designación puede recaer:","o":["en una persona jurídica.","únicamente en una persona física.","únicamente en un familiar.","únicamente en el Ministerio Fiscal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">en una persona jurídica</mark></span>El <span class=\"ref-norma\">art. 4.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La designación puede recaer en una persona jurídica\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-3","p":"Ley Orgánica 1/1982, de 5 de mayo, sobre Protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien ésta haya designado a tal efecto en su testamento. La designación puede recaer en una persona jurídica. No existiendo designación o habiendo fallecido la persona designada, estarán legitimados para recabar la protección _______ de la persona afectada que viviesen al tiempo de su fallecimiento.","o":["El cónyuge.","Los descendientes.","Los ascendientes.","Todos son correctos."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctos</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"estarán legitimados para recabar la protección el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento.\"</span>."},{"i":"7-ia-7318","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. No existiendo designación o habiendo fallecido la persona designada, estarán legitimados para recabar la protección:","o":["el cónyuge y los descendientes exclusivamente.","los parientes hasta el cuarto grado.","el cónyuge, los descendientes y los herederos testamentarios, conforme al procedimiento que se establezca reglamentariamente.","el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento</mark></span>El <span class=\"ref-norma\">art. 4.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"estarán legitimados para recabar la protección el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-132","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida, cuando no exista testamento, corresponde al cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que:","o":["Viviesen al tiempo de su fallecimiento.","Residiesen con él al tiempo de su fallecimiento.","Viviesen al tiempo de ejercer la acción civil.","Tuvieran un vínculo personal real con el fallecido."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Viviesen al tiempo de su fallecimiento</mark></span>El <span class=\"ref-norma\">art. 4.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"No existiendo designación o habiendo fallecido la persona designada, estarán legitimados para recabar la protección el cónyuge, los descendientes, ascendientes y hermanos de la persona afectada que viviesen al tiempo de su fallecimiento.\"</span>."},{"i":"7-ia-7344","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. Señale la INCORRECTA sobre la protección civil del honor, la intimidad y la imagen de las personas fallecidas:","o":["Puede ejercerlas quien el fallecido haya designado en su testamento.","El Ministerio Fiscal puede ejercer las acciones sin límite temporal.","A falta de designación, están legitimados el cónyuge, descendientes, ascendientes y hermanos que vivieran al fallecimiento.","A falta de todos ellos, corresponde al Ministerio Fiscal."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Ministerio Fiscal puede ejercer las acciones sin límite temporal</mark></span>El <span class=\"ref-norma\">art. 4 (señale la incorrecta) de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-86","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde a quien la represente, el ejercicio de las acciones de protección corresponderá al Ministerio Fiscal, que podrá actuar de oficio o a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento 1del afectado.","o":["Setenta años.","Ochenta años.","Noventa años.","Cien años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ochenta años</mark></span>El <span class=\"ref-norma\">art. 4.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"A falta de todos ellos, el ejercicio de las acciones de protección corresponderá al Ministerio Fiscal, que podrá actuar de oficio a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado.\"</span>."},{"i":"7-123","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. El ejercicio de las acciones de protección civil del honor, la intimidad o la imagen de una persona fallecida corresponde al Ministerio Fiscal, que podrá actuar de oficio o a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado.","o":["Setenta años.","Ochenta años.","Noventa años.","Cien años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Ochenta años</mark></span>El <span class=\"ref-norma\">art. 4.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"A falta de todos ellos, el ejercicio de las acciones de protección corresponderá al Ministerio Fiscal, que podrá actuar de oficio a instancia de persona interesada, siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado.\"</span>."},{"i":"7-ia-7319","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. A falta de todos los legitimados, el ejercicio de las acciones de protección de una persona fallecida corresponderá al Ministerio Fiscal, siempre que no hubieren transcurrido más de:","o":["cincuenta años desde el fallecimiento del afectado.","veinte años desde el fallecimiento del afectado.","ochenta años desde el fallecimiento del afectado.","cuatro años desde el fallecimiento del afectado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">ochenta años desde el fallecimiento del afectado</mark></span>El <span class=\"ref-norma\">art. 4.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"siempre que no hubieren transcurrido más de ochenta años desde el fallecimiento del afectado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7320","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Protección de personas fallecidas. En los supuestos de intromisión ilegítima en los derechos de las víctimas de un delito, estará legitimado para ejercer las acciones de protección:","o":["el Ministerio Fiscal exclusivamente.","el ofendido o perjudicado por el delito cometido, haya o no ejercido la acción penal o civil en el proceso penal precedente, y también en todo caso el Ministerio Fiscal.","el ofendido únicamente si ha ejercido la acción penal, sin perjuicio de lo dispuesto en el Derecho nacional, en los términos que establezca el propio Reglamento, salvo que el Estado miembro afectado disponga otra cosa.","el ofendido únicamente si ha ejercido la acción civil."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el ofendido o perjudicado por el delito cometido, haya o no ejercido la acción penal o civil en el proceso penal precedente, y también en todo caso el Ministerio Fiscal</mark></span>El <span class=\"ref-norma\">art. 4.4 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"estará legitimado para ejercer las acciones de protección el ofendido o perjudicado por el delito cometido, haya o no\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 7 — Intromisiones ilegítimas ✱","q":[{"i":"7-155","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo segundo de esta Ley, entre otras:","o":["La publicación de la imagen de una persona en actos públicos o en lugares abiertos al público, sin perjuicio de lo que establezcan los tratados internacionales, en los términos que determine la ley orgánica correspondiente.","La captación de la imagen de una persona que ejerza un cargo público durante un acto público.","El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.","La utilización de la caricatura de una persona de notoriedad pública conforme al uso social."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas</mark></span>El <span class=\"ref-norma\">art. 7 (apartados 1 y 2) de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo segundo de esta Ley: 1. El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.\"</span>"},{"i":"7-ia-7324","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima el emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para:","o":["difundir la imagen de las personas.","grabar o reproducir la vida íntima de las personas.","recopilar datos personales de las personas, en los términos que establezca el propio Reglamento.","localizar a las personas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">grabar o reproducir la vida íntima de las personas</mark></span>El <span class=\"ref-norma\">art. 7.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"apto para grabar o reproducir la vida íntima de las personas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-150","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. De la protección civil del honor, de la intimidad y de la propia imagen. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 2 de esta Ley: la utilización de aparatos de escucha, dispositivos ópticos, o de cualquier otro medio para el conocimiento de la vida íntima de las personas o de manifestaciones o cartas privadas:","o":["Destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción.","No destinadas a quien haga uso de tales medios, salvo su grabación o registro.","Únicamente cuando se produzca su difusión pública.","No destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción</mark></span>El <span class=\"ref-norma\">art. 7.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"2. La utilización de aparatos de escucha, dispositivos ópticos, o de cualquier otro medio para el conocimiento de la vida íntima de las personas o de manifestaciones o cartas privadas no destinadas a quien haga uso de tales medios, así como su grabación, registro o reproducción.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado ✱ en tu temario)</em>"},{"i":"7-9","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por el artículo 2 de esta ley:","o":["La divulgación de hechos relativos a la vida privada de una persona o familia que afecten a su reputación y buen nombre, así como la revelación o publicación del contenido de cartas, memorias u otros escritos personales de carácter íntimo.","La revelación de datos privados de una persona o familia conocidos a través de la actividad profesional u oficial de quienes los revelen.","La utilización del delito por el condenado en sentencia penal firme para conseguir notoriedad pública u obtener provecho económico, o la divulgación de datos falsos sobre los hechos delictivos, cuando ello suponga el menoscabo de la dignidad de las víctimas.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 7 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"1. El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.\"</span>. Los apartados 3 y 4 y el 8 del artículo 7 son también intromisiones ilegítimas; el 3 se refiere a escritos personales de carácter íntimo (no «público»)."},{"i":"7-ia-7325","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la divulgación de hechos relativos a la vida privada de una persona o familia que afecten:","o":["a su reputación y buen nombre, así como la revelación o publicación del contenido de cartas, memorias u otros escritos personales de carácter íntimo.","a su situación patrimonial y a su domicilio, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente.","a su salud y a su religión.","a su honor profesional."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a su reputación y buen nombre, así como la revelación o publicación del contenido de cartas, memorias u otros escritos personales de carácter íntimo</mark></span>El <span class=\"ref-norma\">art. 7.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"que afecten a su reputación y buen nombre\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7326","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la revelación de datos privados de una persona o familia conocidos a través de:","o":["los medios de comunicación, sin perjuicio de lo dispuesto en el Derecho nacional.","las redes sociales.","terceras personas.","la actividad profesional u oficial de quien los revela."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">la actividad profesional u oficial de quien los revela</mark></span>El <span class=\"ref-norma\">art. 7.4 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"conocidos a través de la actividad profesional u oficial de quien los revela\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-97","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tendrán la consideración de intromisiones ilegítimas en el ámbito de protección delimitado por esta ley:","o":["El emplazamiento en cualquier lugar de aparatos de escucha, de filmación, de dispositivos ópticos o de cualquier otro medio apto para grabar o reproducir la vida íntima de las personas.","La revelación de datos privados de una persona o familia conocidos a través de la actividad profesional u oficial de quien los revela.","La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga.","Todos son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todos son correctas</mark></span>El <span class=\"ref-norma\">art. 7 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"4. La revelación de datos privados de una persona o familia conocidos a través de la actividad profesional u oficial de quien los revela. 5. La captación, reproducción o publicación por fotografía, filme, o cualquier otro procedimiento, de la imagen de una persona en lugares o momentos de su vida privada o fuera de ellos, salvo los casos previstos en el artículo octavo, dos. 6. La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga.\"</span>."},{"i":"7-ia-7328","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la utilización del nombre, de la voz o de la imagen de una persona para:","o":["fines informativos o periodísticos, en los términos que establezca el propio Reglamento.","fines publicitarios, comerciales o de naturaleza análoga.","fines científicos o culturales.","fines políticos o electorales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">fines publicitarios, comerciales o de naturaleza análoga</mark></span>El <span class=\"ref-norma\">art. 7.6 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7346","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Señale cuál NO tiene la consideración de intromisión ilegítima según el artículo siete de la Ley:","o":["La utilización de la voz de una persona para fines publicitarios sin su consentimiento.","La revelación de datos privados conocidos a través de la actividad profesional de quien los revela.","El emplazamiento de aparatos de escucha para grabar la vida íntima de las personas.","La captación de la imagen de un personaje público durante un acto público."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La captación de la imagen de un personaje público durante un acto público</mark></span>El <span class=\"ref-norma\">art. 7 (señale la incorrecta) de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"a) Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7329","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la imputación de hechos o la manifestación de juicios de valor a través de acciones o expresiones que lesionen la dignidad de otra persona, menoscabando:","o":["su fama o atentando contra su propia estimación.","su reputación profesional o su patrimonio, salvo que el Estado miembro afectado disponga otra cosa.","su honor familiar o su intimidad.","su libertad ideológica o su religión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">su fama o atentando contra su propia estimación</mark></span>El <span class=\"ref-norma\">art. 7.7 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"menoscabando su fama o atentando contra su propia estimación\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-43","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. En particular, el derecho a la propia imagen no impedirá su captación en un acto público, cuando se trate de personas que ejerzan: Señale la opción incorrecta.","o":["Un cargo público.","Una profesión de notoriedad.","Una profesión de proyección pública.","Una profesión en el ejercicio de funciones públicas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Una profesión en el ejercicio de funciones públicas</mark></span>El <span class=\"ref-norma\">art. 8.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En particular, el derecho a la propia imagen no impedirá: a) Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte durante un acto público o en lugares abiertos al público. b) La utilización de la caricatura de dichas personas, de acuerdo con el uso social. c) La información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca como meramente accesoria.\"</span>."},{"i":"7-ia-7330","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Intromisiones ilegítimas. Tendrá la consideración de intromisión ilegítima la utilización del delito por el condenado en sentencia penal firme para conseguir notoriedad pública u obtener provecho económico, o la divulgación de datos falsos sobre los hechos delictivos, cuando ello suponga:","o":["el menoscabo del honor del condenado.","la alteración del orden público.","la revelación de datos del procedimiento, conforme al procedimiento que se establezca reglamentariamente.","el menoscabo de la dignidad de las víctimas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">el menoscabo de la dignidad de las víctimas</mark></span>El <span class=\"ref-norma\">art. 7.8 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando ello suponga el menoscabo de la dignidad de las víctimas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 8.2 · EL DERECHO A LA PROPIA IMAGEN NO IMPEDIRÁ","q":[{"i":"7-102","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La protección civil del honor, de la intimidad y de la propia imagen quedará delimitada:","o":["Por las leyes y por los usos sociales.","Por las leyes y su desarrollo normativo complementario.","Por las leyes y por las costumbres.","Por la situación jurídica y personal de cada persona."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Por las leyes y por los usos sociales</mark></span>El <span class=\"ref-norma\">art. 8.3 de la LOTC</span> dispone: <span class=\"ref-concepto\">\"Podrá corresponder también a las Secciones el conocimiento y resolución de aquellos asuntos de amparo que la Sala correspondiente les defiera en los términos previstos en esta ley.\"</span>."},{"i":"7-107","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La protección civil del honor, de la intimidad y de la propia imagen. En particular, el derecho a la propia imagen no impedirá:","o":["La utilización de la caricatura de dichas personas, de acuerdo con el uso social.","La información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca como meramente accesoria.","Su captación, reproducción o publicación por cualquier medio, cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte durante un acto público o en lugares abiertos al público.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 8.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En particular, el derecho a la propia imagen no impedirá: a) Su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte durante un acto público o en lugares abiertos al público. b) La utilización de la caricatura de dichas personas, de acuerdo con el uso social. c) La información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca como meramente accesoria.\"</span>."},{"i":"7-108","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. No se reputarán, con carácter general, intromisiones ilegítimas:","o":["La utilización del nombre, de la voz o de la imagen de una persona para fines publicitarios, comerciales o de naturaleza análoga.","Las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley.","Aquellas actuaciones en las que no predomina un interés histórico, científico o cultural relevante.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley</mark></span>El <span class=\"ref-norma\">art. 8.1 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"No se reputará, con carácter general, intromisiones ilegítimas las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley, ni cuando predomine un interés histórico, científico o cultural relevante.\"</span>."},{"i":"7-ia-7331","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. No se reputarán, con carácter general, intromisiones ilegítimas las actuaciones autorizadas o acordadas por la Autoridad competente de acuerdo con la ley, ni cuando:","o":["predomine un interés económico o comercial relevante, sin perjuicio de lo dispuesto en el Derecho nacional.","exista consentimiento tácito del interesado.","predomine un interés histórico, científico o cultural relevante.","se trate de personas fallecidas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">predomine un interés histórico, científico o cultural relevante</mark></span>El <span class=\"ref-norma\">art. 8.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"ni cuando predomine un interés histórico, científico o cultural relevante\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7332","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. El derecho a la propia imagen no impedirá su captación, reproducción o publicación por cualquier medio cuando se trate de personas que ejerzan un cargo público o una profesión de notoriedad o proyección pública y la imagen se capte:","o":["en cualquier lugar y momento.","durante un acto público o en lugares abiertos al público.","durante el ejercicio de su cargo o profesión.","en lugares públicos, con consentimiento previo, en los términos que establezca el propio Reglamento."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">durante un acto público o en lugares abiertos al público</mark></span>El <span class=\"ref-norma\">art. 8.2.a de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"la imagen se capte durante un acto público o en lugares abiertos al público\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7333","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. El derecho a la propia imagen no impedirá la utilización de la caricatura de dichas personas:","o":["de acuerdo con el uso social.","con autorización de la persona caricaturizada.","siempre que no sea ofensiva.","siempre que se haga con fines periodísticos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de acuerdo con el uso social</mark></span>El <span class=\"ref-norma\">art. 8.2.b de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La utilización de la caricatura de dichas personas, de acuerdo con el uso social\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7334","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. El derecho a la propia imagen no impedirá la información gráfica sobre un suceso o acaecimiento público cuando la imagen de una persona determinada aparezca:","o":["como elemento principal de la noticia.","con difuminado del rostro.","con consentimiento de la persona.","como meramente accesoria."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">como meramente accesoria</mark></span>El <span class=\"ref-norma\">art. 8.2.c de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"cuando la imagen de una persona determinada aparezca como meramente accesoria\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7335","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Excepciones a las intromisiones ilegítimas. Las excepciones relativas a personas con cargo público y a la caricatura no serán de aplicación respecto de:","o":["los menores de edad que ejerzan una profesión.","las personas fallecidas.","las autoridades o personas que desempeñen funciones que por su naturaleza necesiten el anonimato de la persona que las ejerza.","las personas que hayan sido condenadas por sentencia firme, salvo que el Estado miembro afectado disponga otra cosa, conforme al procedimiento que se establezca reglamentariamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las autoridades o personas que desempeñen funciones que por su naturaleza necesiten el anonimato de la persona que las ejerza</mark></span>El <span class=\"ref-norma\">art. 8.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"no serán de aplicación respecto de las autoridades o personas que desempeñen funciones que por su naturaleza necesiten el anonimato\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"ART. 9.2 · TUTELA JUDICIAL: MEDIDAS NECESARIAS PARA PONER FIN A LA INTROMISIÓN","q":[{"i":"7-2","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. Las acciones de protección frente a las intromisiones ilegítimas caducarán:","o":["Transcurridos cuatro años desde que el legitimado pudo ejercitarlas.","Transcurridos tres años desde que el legitimado pudo ejercitarlas.","Transcurridos cinco años desde que el legitimado pudo ejercitarlas.","Transcurridos ocho años desde que el legitimado pudo ejercitarlas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Transcurridos cuatro años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9.5 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas.\"</span>."},{"i":"7-10","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para, entre otros:","o":["Prevenir intromisiones inminentes o ulteriores.","La indemnización de los daños y perjuicios causados.","La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para: a) El restablecimiento del perjudicado en el pleno disfrute de sus derechos\"</span>."},{"i":"7-16","p":"Ley Orgánica 1/1982, de 5 de mayo, de Protección Civil del Derecho al Honor, a la Intimidad Personal y Familiar y a la Propia Imagen. En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá, sin perjuicio del derecho de réplica por el procedimiento legalmente previsto:","o":["La publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida.","La publicación siempre se hará realidad de la sentencia condenatoria a costa del condenado con el mismo la misma difusión pública que tuvo la intromisión ilícita","La referencia a la sentencia condenatoria a costa del condenado.","La referencia a la sentencia condenatoria a costa del condenado con el mismo la misma difusión pública que tuvo la intromisión ilícita"],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida</mark></span>Según el <span class=\"ref-norma\">art. 9.2.a de la LO 1/1982</span>: <span class=\"ref-concepto\">\"En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá, sin perjuicio del derecho de réplica por el procedimiento legalmente previsto, la publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida\"</span> (verificado con el texto del temario)."},{"i":"7-71","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para:","o":["El restablecimiento del perjudicado en el pleno disfrute de sus derechos, con la declaración de la intromisión sufrida.","Prevenir intromisiones inminentes o ulteriores.","La indemnización de los daños y perjuicios causados.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"b) Prevenir intromisiones inminentes o ulteriores. c) La indemnización de los daños y perjuicios causados. d) La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.\"</span>."},{"i":"7-90","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos:","o":["Un año desde que el legitimado pudo ejercitarlas.","Dos años desde que el legitimado pudo ejercitarlas.","Tres años desde que el legitimado pudo ejercitarlas.","Cuatro años desde que el legitimado pudo ejercitarlas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Cuatro años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9.5 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas.\"</span>."},{"i":"7-112","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para: señale la INCORRECTA.","o":["El restablecimiento del perjudicado en el pleno disfrute de sus derechos, con la declaración de la intromisión sufrida, y cese inmediato de la misma y la reposición del estado anterior.","Prevenir únicamente las intromisiones inminentes, pero no las ulteriores.","La indemnización de los daños y perjuicios causados.","La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Prevenir únicamente las intromisiones inminentes, pero no las ulteriores</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"b) Prevenir intromisiones inminentes o ulteriores.\"</span>. La ley dice «inminentes o ulteriores»: se previenen las dos clases; la opción B, que excluye las ulteriores, es la incorrecta."},{"i":"7-119","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y a la propia imagen. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para:","o":["El restablecimiento del perjudicado en el pleno disfrute de sus derechos, con la declaración de la intromisión sufrida, el cese inmediato de la misma y la reposición del estado anterior.","Prevenir intromisiones inminentes o ulteriores.","La indemnización de los daños y perjuicios causados.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 9.2 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"b) Prevenir intromisiones inminentes o ulteriores. c) La indemnización de los daños y perjuicios causados. d) La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.\"</span>."},{"i":"7-151","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. De la protección civil del honor, de la intimidad y de la propia imagen. Se presumirá siempre que se acredite la intromisión ilegítima:","o":["La existencia de perjuicio.","La mala fe del causante.","La existencia de daño patrimonial.","La culpa del medio de difusión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La existencia de perjuicio</mark></span>El <span class=\"ref-norma\">art. 9.3 de la LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La existencia de perjuicio se presumirá siempre que se acredite la intromisión ilegítima.\"</span>. <em style=\"color:var(--texto-gris)\">(Pregunta del apartado marcado R13 en tu temario)</em>"},{"i":"7-ia-7336","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. La tutela judicial frente a las intromisiones ilegítimas podrá recabarse por las vías procesales ordinarias o por el procedimiento previsto en la Constitución para la protección de los derechos fundamentales. También podrá acudirse:","o":["a la Agencia Española de Protección de Datos.","cuando proceda, al recurso de amparo ante el Tribunal Constitucional.","al Defensor del Pueblo con carácter vinculante.","a la jurisdicción contencioso-administrativa en todo caso, sin perjuicio de lo dispuesto en el Derecho nacional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando proceda, al recurso de amparo ante el Tribunal Constitucional</mark></span>El <span class=\"ref-norma\">art. 9.1 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"También podrá acudirse, cuando proceda, al recurso de amparo ante el Tribunal Constitucional\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7337","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. La tutela judicial comprenderá la adopción de todas las medidas necesarias para poner fin a la intromisión ilegítima de que se trate y, en particular, las necesarias para el restablecimiento del perjudicado en el pleno disfrute de sus derechos, prevenir intromisiones inminentes o ulteriores, la indemnización de los daños y perjuicios y:","o":["la apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos.","la imposición de una sanción administrativa al infractor, en los términos que establezca el propio Reglamento.","la retirada de la licencia del medio de comunicación.","la inhabilitación del infractor."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus derechos</mark></span>El <span class=\"ref-norma\">art. 9.2 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"La apropiación por el perjudicado del lucro obtenido con la intromisión ilegítima en sus\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7338","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá, sin perjuicio del derecho de réplica, la publicación total o parcial de la sentencia condenatoria:","o":["a costa del perjudicado en un medio de su elección.","a costa del Estado en el «Boletín Oficial del Estado», salvo que el Estado miembro afectado disponga otra cosa.","a costa del condenado en un diario de tirada nacional.","a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida</mark></span>El <span class=\"ref-norma\">art. 9.2.a de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"la publicación total o parcial de la sentencia condenatoria a costa del condenado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7339","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. La existencia de perjuicio se presumirá siempre que se acredite la intromisión ilegítima. La indemnización se extenderá al daño moral, que se valorará atendiendo a las circunstancias del caso y a la gravedad de la lesión, teniendo en cuenta, en su caso:","o":["la capacidad económica del causante de la lesión, conforme al procedimiento que se establezca reglamentariamente.","el beneficio obtenido por el infractor.","la difusión o audiencia del medio a través del que se haya producido.","la notoriedad pública del perjudicado."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la difusión o audiencia del medio a través del que se haya producido</mark></span>El <span class=\"ref-norma\">art. 9.3 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"se tendrá en cuenta, en su caso, la difusión o audiencia del medio a través del que se haya producido\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7340","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. En los casos del artículo sexto, la indemnización por el daño moral:","o":["corresponderá al Ministerio Fiscal.","se entenderá comprendida en la herencia del perjudicado.","corresponderá a los descendientes en todo caso, sin perjuicio de lo dispuesto en el Derecho nacional.","se destinará a fines de interés general."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">se entenderá comprendida en la herencia del perjudicado</mark></span>El <span class=\"ref-norma\">art. 9.4 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"En los casos del artículo sexto, la indemnización se entenderá comprendida en la herencia del perjudicado\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7341","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. Las acciones de protección frente a las intromisiones ilegítimas caducarán transcurridos:","o":["cuatro años desde que el legitimado pudo ejercitarlas.","un año desde que el legitimado pudo ejercitarlas, en los términos que establezca el propio Reglamento.","cinco años desde la intromisión.","dos años desde la intromisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuatro años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9.5 de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"7-ia-7345","p":"Ley Orgánica 1/1982, de 5 de mayo, de protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. Tutela judicial. Señale la INCORRECTA sobre la tutela judicial de los derechos al honor, la intimidad y la propia imagen:","o":["Las acciones caducan transcurridos seis años desde que el legitimado pudo ejercitarlas.","La existencia de perjuicio se presume siempre que se acredite la intromisión ilegítima, sin perjuicio de lo dispuesto en el Derecho nacional.","La indemnización se extiende al daño moral.","Puede acudirse, cuando proceda, al recurso de amparo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las acciones caducan transcurridos seis años desde que el legitimado pudo ejercitarlas</mark></span>El <span class=\"ref-norma\">art. 9 (señale la incorrecta) de LO 1/1982</span> dispone: <span class=\"ref-concepto\">\"caducarán transcurridos cuatro años desde que el legitimado pudo ejercitarlas\"</span>.  <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9 — Tutela judicial ✱ R13","q":[{"i":"7-36","p":"Ley Orgánica sobre protección civil del derecho al honor, a la intimidad personal y familiar y a la propia imagen. En caso de intromisión en el derecho al honor, el restablecimiento del derecho violado incluirá la publicación total o parcial de la sentencia condenatoria a costa del condenado: Señale la opción correcta.","o":["Con al menos la misma difusión pública que tuvo la intromisión sufrida.","Con la misma difusión pública que tuvo la intromisión sufrida, debiendo proyectarse en forma específica en los mismos entornos en que fueron divulgadas.","Con una difusión pública superior a la que tuvo la intromisión sufrida, a efectos de que pueda alcanzar al menos a los mismos que tuvieron conocimiento de la intromisión.","Con una difusión pública."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Con al menos la misma difusión pública que tuvo la intromisión sufrida</mark></span>Según el <span class=\"ref-norma\">art. 9.2.a de la LO 1/1982</span>: <span class=\"ref-concepto\">\"la publicación total o parcial de la sentencia condenatoria a costa del condenado con al menos la misma difusión pública que tuvo la intromisión sufrida\"</span> (verificado con el texto del temario)."}]}];
